parameters.query:
SELECT string_agg(nom, ', ' ORDER BY ordre, nom) AS themes_liste 
FROM newsletter_themes 
WHERE nom != 'Autre';

parameters.jsCode:
const email = $('Loop Over Emails').item.json;
const themes = $('Thèmes disponibles').all().map(i => i.json.theme).join(', ');
const abonneData = $('État abonné existant').all();
const etatAbonne = abonneData.length > 0 ? JSON.stringify(abonneData[0].json) : 'non inscrit';

const prompt = `Tu es l'assistant automatique de gestion d'abonnements de la newsletter "Veille TPE".
Tu reçois un email et tu dois déterminer ce que l'expéditeur souhaite faire.

Email reçu de : ${email.email_expediteur}
---
${email.corps_original}
---

Thèmes disponibles : ${themes}

État actuel de cet abonné : ${etatAbonne}

Détermine :
1. L'action demandée parmi : inscription | desinscription | modification | suggestion_theme | incompris
2. Si inscription ou modification : les thèmes choisis (utilise EXACTEMENT les noms de la liste) et la périodicité (quotidien | hebdomadaire | mensuel)
3. Un texte de réponse en français, ton amical et professionnel, qui :
   - Précise que tu es un assistant automatisé
   - Confirme ce qui a été fait (si action claire)
   - Pour suggestion_theme : indique que la demande est transmise à l'administrateur
   - Pour incompris : explique ce que tu n'as pas compris et donne ces 4 exemples :
     * "Je souhaite m'abonner aux thèmes Finances et Légal, en hebdomadaire"
     * "Je veux me désabonner de la newsletter"
     * "Ajoute le thème Ressources humaines à mes préférences"
     * "Je voudrais recevoir la newsletter tous les mois"

Réponds UNIQUEMENT avec un objet JSON valide, sans texte avant ou après :
{"action": "...", "themes": [], "periodicite": "...", "reponse_texte": "..."}`;

return [{ json: { prompt, commande_id: email.id, email_expediteur: email.email_expediteur, sujet_original: email.sujet_original } }];

values.content:
=You are the automated subscription manager for the News Monitor newsletter.
This sender is ALREADY SUBSCRIBED.

Email received from: {{ $('Emails à traiter').item.json.email_expediteur }}
---
{{ $('Emails à traiter').item.json.corps_original }}
---

Current Subscription:
- Topics: {{ $('État abonné existant').first().json.themes.join(', ') }}
- Frequency: {{ $('État abonné existant').first().json.periodicite }}

RULES:
- If sender wants to adjust topics or change frequency -> action = "modification"
- If sender wants to completely stop receiving emails / unsubscribe -> action = "desinscription"
- If unclear or unrelated -> action = "incompris"
- Provide NO explanation. Output pure JSON only.

Respond ONLY with a valid JSON object:
{"action": "..."}

parameters.jsCode:
const raw = ($json.content || $json.message?.content || '')
  .replace(/```json/ig, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch(e) {
  return [{ json: { 
    _parse_error: true, 
    raw,
    commande_id: $('Emails à traiter').item.json.id, 
    email_expediteur: $('Emails à traiter').item.json.email_expediteur 
  } }];
}

const themes = $('Thèmes disponibles').first().json.themes_liste;
const action = parsed.action || 'incompris';
const prenom = $('État abonné existant').first().json.prenom || '';
const salutation = prenom ? `Bonjour ${prenom}` : 'Bonjour';

const reponses = {
  inscription: `Bonjour\n\nVotre inscription à la newsletter Veille TPE est confirmée. Vous recevrez quotidiennement nos actualités sur les thèmes suivants : ${themes}.\n\nSi vous souhaitez recevoir uniquement certains de ces thèmes, répondez simplement à cet email en nous indiquant lesquels.\n\nCordialement,\nL équipe Veille TPE`,
  desinscription: `${salutation},\n\nVotre désinscription de la newsletter Veille TPE a bien été prise en compte.\n\nCordialement,\nL équipe Veille TPE`,
 modification: `${salutation},\n\nNous avons bien reçu votre demande de modification. Votre demande a été transmise à notre administrateur qui mettra à jour vos préférences dans les plus brefs délais.\n\nCordialement,\nL equipe Veille TPE`,
  incompris: `${salutation},\n\nNous n avons pas bien compris votre demande. Voici quelques exemples :\n- "Je souhaite m abonner aux thèmes Finances et Légal, en hebdomadaire"\n- "Je veux me désabonner de la newsletter"\n- "Passe ma newsletter en mensuel"\n\nCordialement,\nL équipe Veille TPE`
};

const escape = (str) => str.replace(/'/g, "''");

return [{ json: {
  action,
  themes:           [],
  periodicite:      'quotidien',
  reponse_texte:    escape(reponses[action] || reponses.incompris),
  commande_id:      $('Emails à traiter').item.json.id,
  email_expediteur: $('Emails à traiter').item.json.email_expediteur,
  sujet_original:   $('Emails à traiter').item.json.sujet_original
} }];

